			return;
		}
		long classCheckFlags = typeDeclForClassCheck.mods.flags;
		if ((classCheckFlags & (Flags.INTERFACE | Flags.ENUM | Flags.ANNOTATION | RECORD)) != 0) {
			annotationNode.addError("@StandardException is only supported on a class");
			return;
		}

		JCTree extending = Javac.getExtendsClause((JCClassDecl) typeNode.get());
		if (extending == null) {
			annotationNode.addError("@StandardException requires that you extend a Throwable type");
			return;
		}

