			boolean causeParam = constructorKind >= 2;
			Class<?>[] wanted = wantedByKind[constructorKind];
			boolean constructorExists = false;
			JavacNode searchNode = upToTypeNode(typeNode);
			if (searchNode != null && searchNode.get() instanceof JCClassDecl) {
				for (JCTree def : ((JCClassDecl) searchNode.get()).defs) {
					if (!(def instanceof JCMethodDecl)) continue;
					JCMethodDecl md = (JCMethodDecl) def;
					if (!md.name.contentEquals("<init>") || (md.mods.flags & Flags.GENERATEDCONSTR) != 0) continue;
					List<JCVariableDecl> existingParams = md.params;
					boolean paramsAreEqual;
					if (existingParams == null) {
						paramsAreEqual = wanted.length == 0;
					} else if (existingParams.size() != wanted.length) {
						paramsAreEqual = false;
					} else {
						paramsAreEqual = true;
						for (int i = 0; i < existingParams.size(); i++) {
							JCVariableDecl param = existingParams.get(i);
							if (param.vartype == null || !typeMatches(wanted[i], searchNode, param.vartype)) {
